import{b as a,O as s,g as e,j as d}from"./chunks/framework.DSt9LnBW.js";const g=JSON.parse('{"title":"用 JMeter 压一把接口","description":"最近拿本地练习站 testing-online 把接口压测链路又过了一遍：Bearer 登录、关联 Token、压 POST /api/perf/generate，再用 10 / 20 / 50 三档并发对比，最后用命令行出 HTML 报告。","frontmatter":{"date":"2026-09-19T00:00:00.000Z","tags":["性能测试","JMeter","接口压测","Bearer Token","HTML报告"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/testing/jmeter-api-load-test/index.md","filePath":"个人博客/测试/3.用JMeter压一把接口.md","lastUpdated":1790295655000}'),r={name:"blog/testing/jmeter-api-load-test/index.md"};function o(i,t,n,l,h,p){return s(),e("div",null,[...t[0]||(t[0]=[d(`<h1 id="用-jmeter-压一把接口" tabindex="-1">用 JMeter 压一把接口 <a class="header-anchor" href="#用-jmeter-压一把接口" aria-label="Permalink to &quot;用 JMeter 压一把接口&quot;">​</a></h1><p>最近拿本地练习站 <a href="https://github.com/yychuiyan/testing-online" target="_blank" rel="noreferrer">testing-online</a> 把接口压测链路又过了一遍：Bearer 登录、关联 Token、压 <code>POST /api/perf/generate</code>，再用 10 / 20 / 50 三档并发对比，最后用命令行出 HTML 报告。</p><p><img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-01-overview.webp" alt="压测全链路示意"></p><h2 id="一、这次压什么" tabindex="-1">一、这次压什么 <a class="header-anchor" href="#一、这次压什么" aria-label="Permalink to &quot;一、这次压什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>选择</th></tr></thead><tbody><tr><td>被测环境</td><td><code>http://localhost:3001</code></td></tr><tr><td>鉴权</td><td><code>POST /api/auth/login</code> → <code>Authorization: Bearer &lt;token&gt;</code></td></tr><tr><td>压测接口</td><td><code>POST /api/perf/generate</code>（批量生成用户数据）</td></tr><tr><td>Body</td><td><code>{&quot;type&quot;:&quot;users&quot;,&quot;count&quot;:2}</code></td></tr><tr><td>清理</td><td><code>POST /api/perf/clear</code>，<code>{&quot;type&quot;:&quot;users&quot;}</code></td></tr></tbody></table><p>为什么选 generate，而不是用户列表？</p><ul><li>列表是读接口，RT 往往虚低</li><li>generate 一次写入一批数据，更能体会「并发 × 单次成本」</li><li>跑完还能 clear，适合反复练场景对比</li></ul><h2 id="二、从-0-到-1-脚本搭建" tabindex="-1">二、从 0 到 1：脚本搭建 <a class="header-anchor" href="#二、从-0-到-1-脚本搭建" aria-label="Permalink to &quot;二、从 0 到 1：脚本搭建&quot;">​</a></h2><p>目标结构三句话：<strong>先登录、再加压、最后清理</strong>。下面按点击顺序搭，搭完左侧树应大致如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Test Plan</span></span>
<span class="line"><span>├── HTTP 请求默认值                 localhost:3001</span></span>
<span class="line"><span>├── HTTP 信息头管理器               Content-Type: application/json</span></span>
<span class="line"><span>├── setUp 线程组 — 登录获取 token</span></span>
<span class="line"><span>│   └── 登录 POST /api/auth/login</span></span>
<span class="line"><span>│         ├── JSON 提取器           $.data.token → token</span></span>
<span class="line"><span>│         └── JSR223                props.put(&quot;AUTH_TOKEN&quot;, vars.get(&quot;token&quot;))</span></span>
<span class="line"><span>├── 线程组 — 生成用户压测</span></span>
<span class="line"><span>│   ├── Header                      Authorization: Bearer \${__P(AUTH_TOKEN)}</span></span>
<span class="line"><span>│   └── POST /api/perf/generate</span></span>
<span class="line"><span>│         ├── 响应断言              200</span></span>
<span class="line"><span>│         └── JSON 断言             $.success == true</span></span>
<span class="line"><span>├── tearDown 线程组 — 后置清理</span></span>
<span class="line"><span>│   └── POST /api/perf/clear</span></span>
<span class="line"><span>├── 察看结果树（调试用）</span></span>
<span class="line"><span>└── 聚合报告</span></span></code></pre></div><h3 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to &quot;准备工作&quot;">​</a></h3><ol><li>本机启动 testing-online 后端，确认 <code>http://localhost:3001</code> 可访问</li><li>打开 JMeter，保存空计划：<code>Cmd+S</code> → 例如 <code>users-generate.jmx</code></li></ol><blockquote><p>所有添加操作都是：<strong>右键节点 → 添加 → …</strong></p></blockquote><h3 id="步骤-1-http-请求默认值" tabindex="-1">步骤 1：HTTP 请求默认值 <a class="header-anchor" href="#步骤-1-http-请求默认值" aria-label="Permalink to &quot;步骤 1：HTTP 请求默认值&quot;">​</a></h3><p>右键 <strong>测试计划</strong> → 添加 → 配置元件 → <strong>HTTP 请求默认值</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>协议</td><td>http</td></tr><tr><td>服务器名称或 IP</td><td>localhost</td></tr><tr><td>端口号</td><td>3001</td></tr></tbody></table><p>后面每个 HTTP 请求只填「方法 + 路径」即可，不用重复写主机端口。</p><p><img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-02-http-defaults.webp" alt="JMeter HTTP 请求默认值"></p><h3 id="步骤-2-全局-http-信息头管理器" tabindex="-1">步骤 2：全局 HTTP 信息头管理器 <a class="header-anchor" href="#步骤-2-全局-http-信息头管理器" aria-label="Permalink to &quot;步骤 2：全局 HTTP 信息头管理器&quot;">​</a></h3><p>右键 <strong>测试计划</strong> → 添加 → 配置元件 → <strong>HTTP 信息头管理器</strong></p><table tabindex="0"><thead><tr><th>名称</th><th>值</th></tr></thead><tbody><tr><td>Content-Type</td><td>application/json</td></tr></tbody></table><p>登录、generate、clear 都是 JSON Body，全局带上最省事。</p><h3 id="步骤-3-setup-线程组-只跑登录" tabindex="-1">步骤 3：setUp 线程组（只跑登录） <a class="header-anchor" href="#步骤-3-setup-线程组-只跑登录" aria-label="Permalink to &quot;步骤 3：setUp 线程组（只跑登录）&quot;">​</a></h3><p>右键 <strong>测试计划</strong> → 添加 → 线程（用户）→ <strong>setUp 线程组</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>名称</td><td>登录获取 token</td></tr><tr><td>线程数</td><td>1</td></tr><tr><td>Ramp-Up</td><td>0</td></tr><tr><td>循环次数</td><td>1</td></tr></tbody></table><p>用 setUp 而不是普通线程组，是为了<strong>保证登录一定先于业务执行</strong>。</p><h3 id="步骤-4-登录-http-请求" tabindex="-1">步骤 4：登录 HTTP 请求 <a class="header-anchor" href="#步骤-4-登录-http-请求" aria-label="Permalink to &quot;步骤 4：登录 HTTP 请求&quot;">​</a></h3><p>右键 setUp 线程组 → 添加 → 取样器 → <strong>HTTP 请求</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>名称</td><td>登录请求</td></tr><tr><td>方法</td><td><strong>POST</strong>（不要选 GET）</td></tr><tr><td>路径</td><td><code>/api/auth/login</code></td></tr><tr><td>消息体数据</td><td><code>{&quot;username&quot;:&quot;炊烟1号&quot;,&quot;password&quot;:&quot;admin123&quot;}</code></td></tr></tbody></table><p>注意：JSON 填在底部 <strong>「消息体数据」</strong> 大文本框，不是上面的「参数」表。</p><p>成功响应（节选，<code>permissions</code> 等字段略）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;登录成功&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;username&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;炊烟1号&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;token-admin-001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;role&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Token 在 <strong><code>data.token</code></strong>。</p><h3 id="步骤-5-json-提取器拿-token" tabindex="-1">步骤 5：JSON 提取器拿 Token <a class="header-anchor" href="#步骤-5-json-提取器拿-token" aria-label="Permalink to &quot;步骤 5：JSON 提取器拿 Token&quot;">​</a></h3><p>右键「登录请求」→ 添加 → 后置处理器 → <strong>JSON 提取器</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>名称</td><td>提取 Token</td></tr><tr><td>引用名称</td><td>token</td></tr><tr><td>JSON Path 表达式</td><td><code>$.data.token</code></td></tr><tr><td>默认值</td><td>NOT_FOUND</td></tr></tbody></table><p>写错成 <code>$.token</code> 时，后面业务会全是 401。</p><p><img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-03-json-extractor.webp" alt="JMeter JSON 提取器"></p><h3 id="步骤-6-jsr223-把-token-存成全局属性" tabindex="-1">步骤 6：JSR223 把 Token 存成全局属性 <a class="header-anchor" href="#步骤-6-jsr223-把-token-存成全局属性" aria-label="Permalink to &quot;步骤 6：JSR223 把 Token 存成全局属性&quot;">​</a></h3><p>setUp 里的普通变量 <code>\${token}</code> <strong>默认传不到</strong>后面的业务线程组，需要写成 JMeter 属性：</p><p>右键「登录请求」→ 添加 → 后置处理器 → <strong>JSR223 PostProcessor</strong> 语言选 <strong>groovy</strong>，脚本：</p><div class="language-groovy vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">groovy</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">props</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">put(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AUTH_TOKEN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, vars</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">get(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span></code></pre></div><p>业务组稍后用 <code>\${__P(AUTH_TOKEN)}</code> 读取。</p><h3 id="步骤-7-业务线程组" tabindex="-1">步骤 7：业务线程组 <a class="header-anchor" href="#步骤-7-业务线程组" aria-label="Permalink to &quot;步骤 7：业务线程组&quot;">​</a></h3><p>右键 <strong>测试计划</strong> → 添加 → 线程（用户）→ <strong>线程组</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>冒烟建议</th><th>正式再改</th></tr></thead><tbody><tr><td>名称</td><td>生成用户压测</td><td>保持</td></tr><tr><td>线程数</td><td>1</td><td>10 / 20 / 50</td></tr><tr><td>Ramp-Up</td><td>1</td><td>5</td></tr><tr><td>循环次数</td><td>1</td><td>永远（配合调度器持续 10 秒）</td></tr></tbody></table><p>命名写清楚，报告里才不会和「用户信息」之类混淆。</p><blockquote><p><strong>调度器在哪里：</strong> 线程组面板底部有「调度器」勾选框，勾上后才能填「持续时间（秒）」。冒烟阶段保持循环 1，不用管它；正式压测改成「永远」+ 持续 <code>10</code> 秒。<strong>只选「永远」而不勾调度器，它会一直跑到你手动停。</strong></p></blockquote><h3 id="步骤-8-业务组认证头" tabindex="-1">步骤 8：业务组认证头 <a class="header-anchor" href="#步骤-8-业务组认证头" aria-label="Permalink to &quot;步骤 8：业务组认证头&quot;">​</a></h3><p>右键业务线程组 → 添加 → 配置元件 → <strong>HTTP 信息头管理器</strong></p><table tabindex="0"><thead><tr><th>名称</th><th>值</th></tr></thead><tbody><tr><td>Authorization</td><td><code>Bearer \${__P(AUTH_TOKEN)}</code></td></tr></tbody></table><p>这里只加了 Authorization，Content-Type 在全局 Header 里。</p><h3 id="步骤-9-生成用户-http-请求" tabindex="-1">步骤 9：生成用户 HTTP 请求 <a class="header-anchor" href="#步骤-9-生成用户-http-请求" aria-label="Permalink to &quot;步骤 9：生成用户 HTTP 请求&quot;">​</a></h3><p>右键业务线程组 → 添加 → 取样器 → <strong>HTTP 请求</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>名称</td><td>生成用户</td></tr><tr><td>方法</td><td><strong>POST</strong></td></tr><tr><td>路径</td><td><code>/api/perf/generate</code></td></tr><tr><td>消息体数据</td><td><code>{&quot;type&quot;:&quot;users&quot;,&quot;count&quot;:2}</code></td></tr></tbody></table><p><code>count</code> 单次上限 50000（超出会被截断）。这里一律填 <strong>2</strong>：并发压测用「永远 + 持续 10 秒」，请求次数极多，单次写入条数直接决定数据总量——50 并发那档实测打了 12.3 万次请求，乘 2 已是 25 万+ 条，本机内存吃紧；若填 100 就是千万级，直接爆。冒烟时若嫌 2 条看不出效果，临时改 <code>10</code> 即可，正式压测前改回 <code>2</code>。</p><p><img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-04-generate-request.webp" alt="JMeter 生成用户请求配置"></p><h3 id="步骤-10-断言-建议加" tabindex="-1">步骤 10：断言（建议加） <a class="header-anchor" href="#步骤-10-断言-建议加" aria-label="Permalink to &quot;步骤 10：断言（建议加）&quot;">​</a></h3><p>右键「生成用户」→ 添加 → 断言：</p><ol><li><strong>响应断言</strong>：勾选响应代码，模式匹配规则选「等于」，测试模式填 <code>200</code></li><li><strong>JSON 断言</strong>：断言 JSON Path 为 <code>$.success</code>，期望值为 <code>true</code></li></ol><p>这样失败会进 Error%，不会「看着绿但业务其实挂了」。</p><h3 id="步骤-11-teardown-清理" tabindex="-1">步骤 11：tearDown 清理 <a class="header-anchor" href="#步骤-11-teardown-清理" aria-label="Permalink to &quot;步骤 11：tearDown 清理&quot;">​</a></h3><p>右键 <strong>测试计划</strong> → 添加 → 线程（用户）→ <strong>tearDown 线程组</strong></p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>名称</td><td>后置清理</td></tr><tr><td>线程数</td><td>1</td></tr><tr><td>循环</td><td>1</td></tr></tbody></table><p>组内同样加 <strong>HTTP 信息头管理器</strong>：</p><table tabindex="0"><thead><tr><th>名称</th><th>值</th></tr></thead><tbody><tr><td>Authorization</td><td><code>Bearer \${__P(AUTH_TOKEN)}</code></td></tr></tbody></table><p>再加 <strong>HTTP 请求</strong>：</p><table tabindex="0"><thead><tr><th>参数</th><th>值</th></tr></thead><tbody><tr><td>名称</td><td>清理用户</td></tr><tr><td>方法</td><td>POST</td></tr><tr><td>路径</td><td><code>/api/perf/clear</code></td></tr><tr><td>消息体数据</td><td><code>{&quot;type&quot;:&quot;users&quot;}</code></td></tr></tbody></table><p>跑完自动清掉压测用户，只留演示账号。</p><h3 id="步骤-12-监听器" tabindex="-1">步骤 12：监听器 <a class="header-anchor" href="#步骤-12-监听器" aria-label="Permalink to &quot;步骤 12：监听器&quot;">​</a></h3><p>右键 <strong>测试计划</strong>（或业务线程组）→ 添加 → 监听器：</p><table tabindex="0"><thead><tr><th>监听器</th><th>用途</th><th>什么时候用</th></tr></thead><tbody><tr><td>察看结果树</td><td>看单次请求/响应、断言失败原因</td><td><strong>仅调试 / 冒烟</strong></td></tr><tr><td>聚合报告</td><td>样本数、平均、中位数、90%/95%/99%、异常%、吞吐量</td><td>仅调试 / 小规模验证</td></tr><tr><td>汇总报告</td><td>只看总体概况，<strong>没有百分位列</strong></td><td>一般不必加</td></tr></tbody></table><blockquote><p><strong>两点别搞错：</strong></p><ol><li><strong>汇总报告和聚合报告列不一样。</strong> 汇总报告只有 # 样本 / 平均值 / 最小值 / 最大值 / 标准偏差 / 平均字节数 / 异常 % / 吞吐量 / 接收 KB/sec / 发送 KB/sec；想看 <strong>90% / 95% / 99% 百分位</strong>，必须加<strong>聚合报告</strong>。</li><li><strong>正式跑时这些监听器一个都别留。</strong> JMeter 官方最佳实践写得很直白：「Use as few Listeners as possible; if using the <code>-l</code> flag as above they can all be deleted or disabled.」监听器要在压测过程中消费每个样本、在内存里累积统计，吃的是压测机自己的资源；本机练习尤其吃亏——JMeter 和被测服务在同一台机器上。</li></ol></blockquote><h3 id="步骤-13-先冒烟再加压" tabindex="-1">步骤 13：先冒烟再加压 <a class="header-anchor" href="#步骤-13-先冒烟再加压" aria-label="Permalink to &quot;步骤 13：先冒烟再加压&quot;">​</a></h3><ol><li>业务线程组保持 <strong>1 线程 × 1 循环</strong></li><li>点绿色 ▶</li><li>打开察看结果树，确认三步都通： <ul><li>登录：200，能看到 <code>data.token</code></li><li>生成用户：200，<code>success: true</code></li><li>清理用户：200</li></ul></li><li>冒烟通过后，再改线程数做 10 / 20 / 50 场景</li></ol><p>若点启动「没反应」：多半是没加察看结果树，setUp 一瞬间跑完，界面上看不出来。</p><h3 id="补充说明" tabindex="-1">补充说明 <a class="header-anchor" href="#补充说明" aria-label="Permalink to &quot;补充说明&quot;">​</a></h3><ul><li><strong>线程组顺序</strong>：登录用 setUp、清理用 tearDown 即可；若三者都是普通线程组，请在测试计划勾选「独立运行每个线程组」，否则可能并行抢跑。</li><li><strong>跨组 Token</strong>：业务头必须是 <code>Bearer \${__P(AUTH_TOKEN)}</code>，不是 <code>\${token}</code>。</li></ul><h2 id="三、线程、ramp-up、循环、持续时间" tabindex="-1">三、线程、Ramp-Up、循环、持续时间 <a class="header-anchor" href="#三、线程、ramp-up、循环、持续时间" aria-label="Permalink to &quot;三、线程、Ramp-Up、循环、持续时间&quot;">​</a></h2><p>这四个参数最容易混，用一句话分开：</p><table tabindex="0"><thead><tr><th>参数</th><th>管什么</th></tr></thead><tbody><tr><td>线程数</td><td>同时有多少虚拟用户</td></tr><tr><td>Ramp-Up</td><td>这些人多久内到齐</td></tr><tr><td>循环次数</td><td>每人把脚本跑几遍</td></tr><tr><td>持续时间</td><td>整场营业多久（常配合「永远」）</td></tr></tbody></table><h3 id="循环-vs-持续时间" tabindex="-1">循环 vs 持续时间 <a class="header-anchor" href="#循环-vs-持续时间" aria-label="Permalink to &quot;循环 vs 持续时间&quot;">​</a></h3><ul><li>只要「每人打 1 次」→ <strong>循环 = 1</strong>，不必开持续时间</li><li>要「压一段时间」→ <strong>永远 + 持续时间</strong></li></ul><blockquote><p><strong>做并发对比时必须选第二种。</strong> 循环为 1 配快速接口，线程打完就退出，几个线程实际只有 1 个在跑，测的是串行不是并发。</p></blockquote><p>勾了永远再设持续 10 秒时，总请求数 ≈ <code>线程数 × 存活期间能打多少次</code>，会远大于线程数——这是正常的。</p><h3 id="ramp-up-大还是小" tabindex="-1">Ramp-Up 大还是小 <a class="header-anchor" href="#ramp-up-大还是小" aria-label="Permalink to &quot;Ramp-Up 大还是小&quot;">​</a></h3><ul><li>偏小：人几乎同时冲进来，偏浪涌</li><li>偏大：慢慢进场，更像日常负载</li></ul><p>压测场景建议 <strong>5s 左右</strong>，并且<strong>不要超过持续时间</strong>——Ramp-Up 比持续时间还长的话，测试结束前线程都没到齐，标称的并发数是虚的。</p><p><img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-05-thread-group.webp" alt="JMeter 线程组参数"></p><h2 id="四、标准场景-10-20-50-并发" tabindex="-1">四、标准场景：10 / 20 / 50 并发 <a class="header-anchor" href="#四、标准场景-10-20-50-并发" aria-label="Permalink to &quot;四、标准场景：10 / 20 / 50 并发&quot;">​</a></h2><p>三档<strong>分开跑</strong>，每次只改<strong>线程数</strong>一个参数，其余全部保持不变——变量唯一，对比才有意义。</p><h3 id="统一的配方" tabindex="-1">统一的配方 <a class="header-anchor" href="#统一的配方" aria-label="Permalink to &quot;统一的配方&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>值</th><th>说明</th></tr></thead><tbody><tr><td>线程数</td><td>10 / 20 / 50</td><td><strong>唯一要改的就是它</strong></td></tr><tr><td>Ramp-Up</td><td>5s</td><td>5 秒内线程全部到齐</td></tr><tr><td>循环</td><td>永远（勾选）</td><td>线程打完不退出，持续发请求</td></tr><tr><td>调度器</td><td>勾选，持续时间 <strong>10</strong> 秒</td><td>压满 10 秒后停止</td></tr><tr><td>count</td><td><strong>2</strong></td><td>每次只写 2 条，控制内存</td></tr><tr><td>登录/清理</td><td>1 线程 × 1 次</td><td>不动</td></tr></tbody></table><p>三档对应的并发水位：</p><table tabindex="0"><thead><tr><th>档位</th><th>实际并发</th><th>用途</th></tr></thead><tbody><tr><td>10 并发</td><td>10</td><td>轻度，日常水位</td></tr><tr><td>20 并发</td><td>20</td><td>中度，看 RT 是否劣化</td></tr><tr><td>50 并发</td><td>50</td><td>重度，探吞吐的<strong>上限</strong>在哪</td></tr></tbody></table><blockquote><p><strong>为什么用「永远 + 持续时间」而不是「循环 1」？</strong> 这是最容易埋的坑——循环为 1 配快速接口时，线程打完立刻退出，10 个线程实际只有 1 个在跑，根本测不出并发。</p></blockquote><h3 id="执行顺序" tabindex="-1">执行顺序 <a class="header-anchor" href="#执行顺序" aria-label="Permalink to &quot;执行顺序&quot;">​</a></h3><ol><li>GUI 用 1 线程冒烟，确认登录 + generate + clear 都通</li><li>把所有 GUI 监听器禁用或删除，<code>Cmd+S</code> 保存 jmx</li><li>冒烟通过后切命令行，三档依次跑，每档只改线程数</li><li>每档之间确认清理完成，再跑下一档</li></ol><blockquote><p><strong>提示：GUI 跑和命令行跑不是一回事。</strong> GUI 点 ▶ 适合冒烟调试，真正的压测数字建议用命令行跑。</p></blockquote><h2 id="五、gui-运行-vs-命令行运行" tabindex="-1">五、GUI 运行 vs 命令行运行 <a class="header-anchor" href="#五、gui-运行-vs-命令行运行" aria-label="Permalink to &quot;五、GUI 运行 vs 命令行运行&quot;">​</a></h2><p>搭好脚本后，正式跑之前先分清这两种执行方式——<strong>它们不是一回事</strong>。</p><table tabindex="0"><thead><tr><th></th><th>GUI（点 ▶）</th><th>命令行（<code>-n</code>）</th></tr></thead><tbody><tr><td>本质</td><td>一边压测一边渲染界面</td><td>只跑压测，不渲染</td></tr><tr><td>资源占用</td><td>JMeter 界面和被测服务抢 CPU / 内存</td><td>省下的资源都用于施压</td></tr><tr><td>结果监听器</td><td>挂着监听器（尤其察看结果树）吃内存</td><td>不加载界面监听器，更接近真实压力</td></tr><tr><td>数据可信度</td><td>线程一多，测出来的数字偏悲观</td><td>相对更准，适合正式对比</td></tr><tr><td>适合场景</td><td>调脚本、看单次响应</td><td>10 / 20 / 50 并发对比、出报告</td></tr></tbody></table><p><strong>推荐做法：</strong></p><ol><li>GUI 只用来<strong>搭脚本 + 冒烟</strong>（1 线程 × 1 循环，开察看结果树确认三步都通）</li><li>调通后<strong>把所有 GUI 监听器禁用或删除</strong>（不只是察看结果树），<code>Cmd+S</code> 保存 <code>.jmx</code></li><li>正式跑三档都切到命令行，分别输出报告目录：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 每档只改线程数（10 / 20 / 50），其余参数保持不变</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jmeter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users-generate.jmx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> result-10.jtl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report-10</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jmeter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users-generate.jmx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> result-20.jtl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report-20</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jmeter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> users-generate.jmx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> result-50.jtl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report-50</span></span></code></pre></div><p>用浏览器打开 HTML 报告对比，而不是在 GUI 监听器里读数字。</p><p>参数含义：<code>-n</code> 非 GUI、<code>-t</code> 测试计划、<code>-l</code> 结果文件、<code>-e</code> 生成报告、<code>-o</code> 报告输出目录。命令在保存 <code>.jmx</code> 的目录下执行（或把 <code>-t</code> 写成绝对路径）；<code>-o</code> 目录不能已存在。</p><blockquote><p>一句话：<strong>GUI 用来写，命令行用来跑，HTML 用来看。</strong> 本机练习尤其明显——界面渲染本身就可能占掉一两个并发的能力。</p></blockquote><p>三档跑完，HTML 报告里的 <strong>Statistics</strong> 表长这样（它是所有报告里列最全的一张表）：</p><p><strong>10并发</strong> <img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-06-report-10.webp" alt="10 并发 HTML 报告 Statistics"></p><p><strong>20并发</strong> <img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-07-report-20.webp" alt="20 并发 HTML 报告 Statistics"></p><p><strong>50并发</strong> <img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-08-report-50.webp" alt="50 并发 HTML 报告 Statistics"></p><h2 id="六、报告怎么看" tabindex="-1">六、报告怎么看 <a class="header-anchor" href="#六、报告怎么看" aria-label="Permalink to &quot;六、报告怎么看&quot;">​</a></h2><h3 id="gui-监听器-只用于调脚本和小规模验证" tabindex="-1">GUI 监听器：只用于调脚本和小规模验证 <a class="header-anchor" href="#gui-监听器-只用于调脚本和小规模验证" aria-label="Permalink to &quot;GUI 监听器：只用于调脚本和小规模验证&quot;">​</a></h3><p>正式跑的三档数据全部来自 HTML 报告——GUI 里那几张表，正式压测时应该已经删掉了。它们只适合<strong>调脚本、小并发（1~2 线程）快速验证</strong>时扫一眼：监听器要在压测过程中累积统计，行数一多就吃内存，还会和被测服务抢 CPU。</p><p>真要临时看一眼，加<strong>聚合报告</strong>（汇总报告没有百分位列），盯「生成用户」那一行：</p><table tabindex="0"><thead><tr><th>列</th><th>先看什么</th></tr></thead><tbody><tr><td>异常 %</td><td>必须先是 <strong>0</strong></td></tr><tr><td># 样本</td><td>是否<strong>远大于</strong>线程数（证明是真并发）</td></tr><tr><td>平均值、P90</td><td>50 比 10 涨了多少</td></tr><tr><td>吞吐量</td><td>是否随并发上涨——<strong>不涨就是到顶了</strong></td></tr></tbody></table><p>登录、清理行的 RT 可以忽略，别和业务行混读。</p><h3 id="命令行-html-报告" tabindex="-1">命令行：HTML 报告 <a class="header-anchor" href="#命令行-html-报告" aria-label="Permalink to &quot;命令行：HTML 报告&quot;">​</a></h3><p><img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-09-dashboard.webp" alt="JMeter HTML 报告顶部总览"></p><p><code>-e -o</code> 会在跑完压测后<strong>顺带</strong>把 HTML 报告生成到指定目录，不用跑两遍。</p><p>如果之前只跑了 <code>-l</code> 没加 <code>-e -o</code>，可以拿现成的 <code>.jtl</code> 单独补报告（这条不重新压测）：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jmeter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> result-10.jtl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report-10</span></span></code></pre></div><p>浏览器打开 <code>report-10/index.html</code> / <code>report-20/index.html</code> / <code>report-50/index.html</code>：</p><table tabindex="0"><thead><tr><th>位置</th><th>看什么</th></tr></thead><tbody><tr><td>APDEX</td><td>把响应时间折算成 0~1 的满意度分数，适合对外汇报</td></tr><tr><td>Statistics</td><td>按标签分行，对比业务请求的 Avg / P90 / P95 / Error% / TPS</td></tr><tr><td><strong>Active Threads Over Time</strong></td><td>活跃线程数——<strong>验证并发是否真的达到了目标线程数</strong></td></tr><tr><td>Response Times Over Time</td><td>RT 是否随时间爬升</td></tr><tr><td>Errors</td><td>有失败时看原因</td></tr></tbody></table><blockquote><p>压测时先看 <strong>Active Threads Over Time</strong>：曲线没爬到目标线程数，说明 Ramp-Up 太长或测试提前结束了，后面的 RT / TPS 都不可信。</p></blockquote><p><code>-o</code> 目录已存在会报错，删掉旧目录或加 <code>-f</code>。</p><h2 id="七、对比时怎么下判断" tabindex="-1">七、对比时怎么下判断 <a class="header-anchor" href="#七、对比时怎么下判断" aria-label="Permalink to &quot;七、对比时怎么下判断&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>含义</th></tr></thead><tbody><tr><td>Error% = 0，P95 略升</td><td>正常，并发高了稍慢</td></tr><tr><td>Error% &gt; 0</td><td>先修脚本/鉴权/断言，别谈性能</td></tr><tr><td>P95 涨很多、吞吐几乎不涨</td><td>接近瓶颈（本机练习站很常见）</td></tr><tr><td>样本数对不上</td><td>检查循环、是否勾了永远、是否中途停止</td></tr></tbody></table><p>记住：这里比的是<strong>相对差异</strong>（10 → 20 → 50 各档之间差多少），不是「系统能扛多少线上用户」。</p><h2 id="八、三档跑完-看到了什么" tabindex="-1">八、三档跑完，看到了什么 <a class="header-anchor" href="#八、三档跑完-看到了什么" aria-label="Permalink to &quot;八、三档跑完，看到了什么&quot;">​</a></h2><p>三档按上面的配方各跑一遍（都是跑满 10 秒，峰值线程数也确实是 10 / 20 / 50），数据摆在一起是这样：</p><table tabindex="0"><thead><tr><th>档位</th><th>样本数</th><th>吞吐量/s</th><th>平均</th><th>P90</th><th>P95</th><th>P99</th><th>最大值</th></tr></thead><tbody><tr><td>10 并发</td><td>130,280</td><td>13,027</td><td>0.58ms</td><td>1ms</td><td>1ms</td><td>2ms</td><td>5ms</td></tr><tr><td>20 并发</td><td>127,700</td><td>12,766</td><td>1.18ms</td><td>2ms</td><td>3ms</td><td>3ms</td><td>26ms</td></tr><tr><td>50 并发</td><td>123,486</td><td>12,321</td><td>3.04ms</td><td>5ms</td><td>5ms</td><td>7ms</td><td>14ms</td></tr></tbody></table><blockquote><p>HTML 报告里 <code>pct1 / pct2 / pct3</code> 分别对应 <strong>90th / 95th / 99th</strong> 百分位，别看到 pct1 就当成 P95。</p></blockquote><h3 id="反常的地方-吞吐不涨-延迟涨" tabindex="-1">反常的地方：吞吐不涨，延迟涨 <a class="header-anchor" href="#反常的地方-吞吐不涨-延迟涨" aria-label="Permalink to &quot;反常的地方：吞吐不涨，延迟涨&quot;">​</a></h3><p>按直觉，并发从 10 加到 50，吞吐应该跟着涨。实际是：</p><ul><li><strong>吞吐几乎不动</strong>：13,027 → 12,766 → 12,321，甚至略微下降</li><li><strong>延迟成倍上涨</strong>：平均 0.58 → 1.18 → 3.04ms，P90 从 1ms 涨到 5ms</li></ul><p>这说明系统已经<strong>饱和</strong>了——再加线程压不出更多处理能力，多出来的并发只能排队，表现就是延迟变高。</p><h3 id="看每秒明细更直观" tabindex="-1">看每秒明细更直观 <a class="header-anchor" href="#看每秒明细更直观" aria-label="Permalink to &quot;看每秒明细更直观&quot;">​</a></h3><p>把 <code>.jtl</code> 按秒切开，看每秒处理了多少请求、平均延迟多少：</p><table tabindex="0"><thead><tr><th>时间</th><th>10 并发（请求/延迟）</th><th>20 并发（请求/延迟）</th><th>50 并发（请求/延迟）</th></tr></thead><tbody><tr><td>第 1 秒</td><td>13,294 / 0.24ms</td><td>13,246 / 0.47ms</td><td>10,422 / 1.43ms</td></tr><tr><td>第 3 秒</td><td>13,378 / 0.54ms</td><td>13,679 / 1.04ms</td><td>12,598 / 2.78ms</td></tr><tr><td>第 5 秒</td><td>14,174 / 0.69ms</td><td>12,728 / 1.56ms</td><td>13,886 / 3.59ms</td></tr><tr><td>第 7 秒</td><td>14,461 / 0.68ms</td><td>13,929 / 1.42ms</td><td>13,633 / 3.65ms</td></tr><tr><td>第 9 秒</td><td>14,180 / 0.69ms</td><td>13,512 / 1.47ms</td><td>14,074 / 3.54ms</td></tr></tbody></table><p>三档最后都稳定在 <strong>1.3～1.4 万/秒</strong>，谁也不比谁高。而且延迟从第 5 秒（Ramp-Up 结束）起就平了，不再往上爬——这排除了「数据越积越多拖慢服务」的可能，剩下的解释就是纯粹的排队。</p><h3 id="用-little-定律算一下" tabindex="-1">用 Little 定律算一下 <a class="header-anchor" href="#用-little-定律算一下" aria-label="Permalink to &quot;用 Little 定律算一下&quot;">​</a></h3><p>排队论里有个很直观的关系：</p><blockquote><p><strong>在途请求数 = 吞吐量 × 延迟</strong></p></blockquote><p>代入三档数据（延迟换算成秒）：</p><table tabindex="0"><thead><tr><th>档位</th><th>计算</th><th>服务端在途请求</th><th>占线程数</th></tr></thead><tbody><tr><td>10</td><td>13027 × 0.000578</td><td>7.5</td><td>75%</td></tr><tr><td>20</td><td>12766 × 0.001176</td><td>15.0</td><td>75%</td></tr><tr><td>50</td><td>12321 × 0.003036</td><td>37.4</td><td>75%</td></tr></tbody></table><p>比值都稳定在 <strong>75%</strong>。这验证了两件事：</p><ol><li>线程数确实转化成了并发（剩下 25% 的时间花在客户端和网络上），不是「循环 1」那种假并发</li><li>多出来的并发全部排进队列、变成了延迟，而不是更强的处理能力</li></ol><h3 id="为什么卡在-1-3-万" tabindex="-1">为什么卡在 1.3 万 <a class="header-anchor" href="#为什么卡在-1-3-万" aria-label="Permalink to &quot;为什么卡在 1.3 万&quot;">​</a></h3><p>这台练习站是 Express + Node.js，几个现实约束：</p><ol><li><strong>Node.js 单线程事件循环</strong>：所有请求在一个 CPU 核心上排队。1.3 万/秒 ≈ 每请求 77µs CPU，对「解析 JSON + 序列化响应 + push 数组」来说基本是单核上限</li><li><strong>JMeter 和被压服务同一台机器</strong>：线程越多，JMeter 自己吃掉的 CPU 越多，反过来挤压服务端——这就是 50 并发吞吐反而略低的原因</li><li><strong>数据无界增长</strong>：一轮 13 万次请求 × 每次 2 条 = 26 万个对象堆在内存里，GC 压力会随测试推进增加</li></ol><p>顺带排查过一个疑点：鉴权中间件里有 <code>users.find()</code>，看着像 O(n)。但管理员账号在数组第 0 位，<code>find</code> 立刻返回，实际是 O(1)，不是瓶颈。</p><h3 id="这个结论比「堆线程」值钱" tabindex="-1">这个结论比「堆线程」值钱 <a class="header-anchor" href="#这个结论比「堆线程」值钱" aria-label="Permalink to &quot;这个结论比「堆线程」值钱&quot;">​</a></h3><ul><li><strong>10 并发时其实已经到顶了</strong>，后面两档只是把队列拉长</li><li>真要提升得先解决单核瓶颈（多进程 / cluster / 换一台压测机），而不是继续加线程</li><li>本机练习站的饱和点跟线上服务没有任何关系，<strong>结论只能做相对参考</strong></li></ul><blockquote><p>压测的目标不是把线程数堆高，而是找到那个「再加线程也不再涨」的拐点。这次很幸运，10 并发就摸到了。</p></blockquote><h2 id="九、固定循环-vs-持续时长" tabindex="-1">九、固定循环 vs 持续时长 <a class="header-anchor" href="#九、固定循环-vs-持续时长" aria-label="Permalink to &quot;九、固定循环 vs 持续时长&quot;">​</a></h2><p>为什么并发场景要用「永远 + 持续时间」，而不是「循环 1」？这次踩得最深的坑就在这里。</p><h3 id="循环-1-时-其实没有并发" tabindex="-1">循环 = 1 时，其实没有并发 <a class="header-anchor" href="#循环-1-时-其实没有并发" aria-label="Permalink to &quot;循环 = 1 时，其实没有并发&quot;">​</a></h3><p>线程数 10、Ramp-Up 5s、循环 1 跑一遍，从 <code>.jtl</code> 里看线程的时间戳：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生成用户压测 1-1    t = 0.00s</span></span>
<span class="line"><span>生成用户压测 1-2    t = 0.50s</span></span>
<span class="line"><span>生成用户压测 1-3    t = 1.00s</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>生成用户压测 1-10   t = 4.50s</span></span></code></pre></div><p>Ramp-Up 把 10 个线程按 500ms 一个依次放出来，而每个线程打完一个请求（约 3ms）就结束了。所以<strong>任意时刻只有一个线程在跑</strong>——看 <code>.jtl</code> 的 <code>grpThreads</code> 列（当前活跃线程数），全程都是 <strong>1</strong>。</p><p>报告里 <code>#Samples = 10</code> 看着没错，但那是 4.8 秒里<strong>串行</strong>打出来的 10 次，不是 10 个用户同时在线。</p><h3 id="永远-持续时长才是真并发" tabindex="-1">永远 + 持续时长才是真并发 <a class="header-anchor" href="#永远-持续时长才是真并发" aria-label="Permalink to &quot;永远 + 持续时长才是真并发&quot;">​</a></h3><p>改成「永远 + 持续 10 秒」后，线程打完不退出，5 秒后全部存活。同样看 <code>grpThreads</code>：</p><table tabindex="0"><thead><tr><th>配置</th><th>峰值并发线程</th></tr></thead><tbody><tr><td>循环 1 + Ramp-Up 5s</td><td><strong>1</strong></td></tr><tr><td>永远 + 持续 10s</td><td><strong>等于线程数</strong></td></tr></tbody></table><p>这才是真的在压「N 个用户同时在用」。</p><h3 id="两种配置怎么选" tabindex="-1">两种配置怎么选 <a class="header-anchor" href="#两种配置怎么选" aria-label="Permalink to &quot;两种配置怎么选&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>循环 = 1（固定次数）</th><th>永远 + 持续 10s</th></tr></thead><tbody><tr><td>线程存活</td><td>打完即退</td><td>一直活着</td></tr><tr><td>实际并发</td><td>常常只有 1</td><td>≈ 线程数</td></tr><tr><td>样本数</td><td>≈ 线程数</td><td>由吞吐决定，很多</td></tr><tr><td>适合</td><td>冒烟、验证脚本连通性</td><td>并发 / 负载对比</td></tr></tbody></table><blockquote><p><strong>Ramp-Up 别超过持续时间。</strong> Ramp-Up 设 15s、持续只有 10s 时，测试在第 10 秒就结束，线程还没启动完（实测峰值只到 34 个）——名义 50 并发，实际只有 34。</p></blockquote><p>持续压还多一个观察点：<strong>Response Times Over Time</strong> 那条线。前半段平稳、后半段开始上翘，通常说明有资源在累积（内存、连接、GC），这类问题短压测看不出来。</p><p><img src="https://op.yychuiyan.com/docs-blog/jmeter-api-load-test-10-b-response-times.webp" alt="持续负载响应时间曲线"></p><h3 id="注意" tabindex="-1">注意 <a class="header-anchor" href="#注意" aria-label="Permalink to &quot;注意&quot;">​</a></h3><ol><li>跑完确认 tearDown 清理成功（持续压会造大量用户）</li><li>正式跑时把 GUI 监听器<strong>全部禁用或删除</strong>（官方最佳实践：用了 <code>-l</code> 就都可以删掉），只看命令行生成的 HTML 报告</li><li>本机练习站结论仍是相对参考，不代表线上容量</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>接口压测在 JMeter 里，真正要固化的不是元件清单，而是习惯：</p><ol><li>鉴权一次、业务反复、收尾清理</li><li>并发档位分开跑、参数只改一处</li><li>GUI 调通，CLI 出数</li><li>先看 Error%，再看 P95 和吞吐</li><li>吞吐不再随并发上涨，就是到拐点了——继续加线程只会加延迟</li><li>练习站结论只做相对对比</li></ol>`,177)])])}const k=a(r,[["render",o]]);export{g as __pageData,k as default};
